INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6774265, 1015271, 142363, '<td valign="top">I actually loved this one - symmetry on so many levels - maybe not identically symmetrical, but color-wise, shape-wise, and a really good yin-yang feeling to it.  I felt symmetry of spirit in it - which is maybe reading too much into it, but it still felt good.  Such a beautiful shot, and I agree with the framing being awesome.</td>', 'I actually loved this one - symmetry on so many levels - maybe not identically symmetrical, but color-wise, shape-wise, and a really good yin-yang feeling to it.  I felt symmetry of spirit in it - which is maybe reading too much into it, but it still felt good.  Such a beautiful shot, and I agree with the framing being awesome.', '2012-05-21 09:03:44.000000', NULL, 0),
(6774277, 1015223, 59029, '<td valign="top">Woohoo so glad to see you back where you belong!! Congrats Deb!</td>', 'Woohoo so glad to see you back where you belong!! Congrats Deb!', '2012-05-21 09:10:10.000000', NULL, 0),
(6774280, 1015223, 43463, '<td valign="top">Look at you Deb! You have been smashing through your competition in the BOYA side challenge. I love the textures and detail seen in the tail and fish scales. To have the tail extent out of the bottom right corner in a square crop was an excellent decision for it calls the eye''s attention to all the shapes, texture, and details.</td>', 'Look at you Deb! You have been smashing through your competition in the BOYA side challenge. I love the textures and detail seen in the tail and fish scales. To have the tail extent out of the bottom right corner in a square crop was an excellent decision for it calls the eye''s attention to all the shapes, texture, and details.', '2012-05-21 09:14:17.000000', NULL, 0),
(6774296, 1015385, 12611, '<td valign="top">like a powdery Albrecht Durer pressed wood piece. excellent.</td>', 'like a powdery Albrecht Durer pressed wood piece. excellent.', '2012-05-21 09:42:10.000000', NULL, 0),
